def get_levels(paren_string: str) -> int:
    """ Recursive helper function to count the depth of nesting for a single group of nested parentheses.

    Input is either the beginning of a single parentheses group or the end of such group which is represented with
    either '(', ')', '(' or ')'.
    E.g. ()() -> 1
    >>> get_levels('(()())')
    2
    """
    open_brace_count = 0
    if not paren_string:
        return 0

    if paren_string[0] == '(':
        open_brace_count += 1

    if paren_string[0] == ')':
        open_brace_count -= 1

    if open_brace_count >= 1:
        return get_levels paren_string[1:paren_string.find(')')] + 1
    elif open_brace_count == 0:
        return get_levels paren_string[1:paren_string.find(')')]
    elif open_brace_count == -1:
        return get_levels paren_string[1:paren_string.find('(')] + 1


