def parse_nested_parens_subgroup(paren_string: str) -> List[int]:
    """ Input to this function is a string representing a single group of parentheses.
    If the string has no nested groups then the result is the same length as the string.
    E.g. () has one level of nesting while ()() has two levels and is twice as long as the input string.

