def median(numbers: List[float]) -> float:
    """ For a given list of numbers, calculate the median value in this
    dataset.
    Median is the value separating the higher half from the lower half
    of a data sample.
    >> median([3, 1, 2, 4, 5])
    3
    """
    sorted_nums = sorted(numbers)
    num_of_nums = len(sorted_nums)
    if num_of_nums % 2 == 0:
        return round((sorted_nums[num_of_nums // 2 - 1] + sorted_nums[num_of_nums // 2]) / 2)
    else:
        return round(sorted_nums[num_of_nums // 2])


